use vstd::prelude::*;

verus! {

/// Returns a new vector with the elements of `m` in reverse order.
///
/// Postcondition:
/// * `result.len() == m.len()`
/// * For all indices `i` in-bounds, `result[i] == m[m.len()-1-i]`
///
/// Works for all lengths, including `0`.
fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == m.len(),
        forall|i: int|
            0 <= i && i < m.len() ==> result[i] == m[m.len() - 1 - i],
{
    let n = m.len();
    let mut result: Vec<f32> = Vec::with_capacity(n);
    let mut j: usize = 0;

    while j < n
        invariant
            result.len() == j,
            result.len() <= n,
            forall|i: int|
                0 <= i && i < j ==> result[i] == m[n - 1 - i],
    {
        let idx = n - 1 - j;
        result.push(m[idx]);
        j += 1;
    }

    result
}

} // verus!